div.script:
document.addEventListener('DOMContentLoaded', function () {
    var body = document.getElementById('hrInvoiceLinesBody');
    var addBtn = document.getElementById('hrInvoiceAddLine');
    var applyDiscount = document.getElementById('hrInvoiceApplyDiscount');
    var discountBox = document.getElementById('hrInvoiceDiscountBox');
    var discountMode = document.getElementById('hrInvoiceDiscountMode');
    var manualBox = document.getElementById('hrInvoiceManualDiscountBox');
    var percentageBox = document.getElementById('hrInvoicePercentageDiscountBox');
    var manualDiscount = document.getElementById('hrInvoiceManualDiscount');
    var percentageDiscount = document.getElementById('hrInvoicePercentageDiscount');
    var salesTaxInput = document.getElementById('hrInvoiceSalesTax');

    function parseNumber(value) {
        var number = parseFloat(String(value || '0').replace(',', ''));
        return isNaN(number) ? 0 : number;
    }

    function formatMoney(value) {
        return 'Rs. ' + value.toFixed(2);
    }

    function updateLineNames(row, index) {
        var itemType = row.querySelector('select');
        var description = row.querySelector('textarea');
        var quantity = row.querySelector('.hr-invoice-line-qty');
        var unitPrice = row.querySelector('.hr-invoice-line-price');

        if (itemType) {
            itemType.name = 'line_item_type_' + index;
        }
        if (description) {
            description.name = 'line_description_' + index;
        }
        if (quantity) {
            quantity.name = 'line_quantity_' + index;
        }
        if (unitPrice) {
            unitPrice.name = 'line_unit_price_' + index;
        }
    }

    function renumberRows() {
        var rows = body.querySelectorAll('.hr-invoice-line-row');
        rows.forEach(function (row, index) {
            updateLineNames(row, index + 1);
        });
    }

    function updateDiscountVisibility() {
        var enabled = applyDiscount && applyDiscount.checked;
        var mode = discountMode ? discountMode.value : 'manual';

        if (discountBox) {
            discountBox.style.display = enabled ? 'flex' : 'none';
        }

        if (manualBox) {
            manualBox.style.display = enabled && mode === 'manual' ? 'block' : 'none';
        }

        if (percentageBox) {
            percentageBox.style.display = enabled && mode === 'percentage' ? 'block' : 'none';
        }

        calculateTotals();
    }

    function calculateTotals() {
        var gross = 0;

        body.querySelectorAll('.hr-invoice-line-row').forEach(function (row) {
            var qty = parseNumber(row.querySelector('.hr-invoice-line-qty')?.value);
            var price = parseNumber(row.querySelector('.hr-invoice-line-price')?.value);
            var amount = qty * price;

            gross += amount;

            var amountLabel = row.querySelector('.hr-invoice-line-amount');
            if (amountLabel) {
                amountLabel.textContent = formatMoney(amount);
            }
        });

        var discountAmount = 0;

        if (applyDiscount && applyDiscount.checked) {
            if (discountMode && discountMode.value === 'percentage') {
                var percent = parseNumber(percentageDiscount ? percentageDiscount.value : 0);
                if (percent < 0) {
                    percent = 0;
                }
                if (percent > 100) {
                    percent = 100;
                }
                discountAmount = gross * percent / 100;
            } else {
                discountAmount = parseNumber(manualDiscount ? manualDiscount.value : 0);
            }
        }

        if (discountAmount < 0) {
            discountAmount = 0;
        }

        if (discountAmount > gross) {
            discountAmount = gross;
        }

        var net = gross - discountAmount;
        var taxPercent = parseNumber(salesTaxInput ? salesTaxInput.value : 0);
        if (taxPercent < 0) {
            taxPercent = 0;
        }

        var tax = net * taxPercent / 100;
        var finalTotal = net + tax;

        document.getElementById('hrInvoiceGrossAmount').textContent = formatMoney(gross);
        document.getElementById('hrInvoiceDiscountAmount').textContent = formatMoney(discountAmount);
        document.getElementById('hrInvoiceTaxAmount').textContent = formatMoney(tax);
        document.getElementById('hrInvoiceNetAmount').textContent = formatMoney(net);
        document.getElementById('hrInvoiceFinalTotal').textContent = formatMoney(finalTotal);
    }

    if (addBtn && body) {
        addBtn.addEventListener('click', function () {
            var rows = body.querySelectorAll('.hr-invoice-line-row');
            var sourceRow = rows.length ? rows[rows.length - 1] : null;

            if (!sourceRow) {
                return;
            }

            var newRow = sourceRow.cloneNode(true);

            var description = newRow.querySelector('textarea');
            var quantity = newRow.querySelector('.hr-invoice-line-qty');
            var unitPrice = newRow.querySelector('.hr-invoice-line-price');
            var amountLabel = newRow.querySelector('.hr-invoice-line-amount');

            if (description) {
                description.value = '';
            }
            if (quantity) {
                quantity.value = '1.0';
            }
            if (unitPrice) {
                unitPrice.value = '';
            }
            if (amountLabel) {
                amountLabel.textContent = 'Rs. 0.00';
            }

            body.appendChild(newRow);
            renumberRows();
            calculateTotals();
        });
    }

    if (body) {
        body.addEventListener('click', function (event) {
            var removeBtn = event.target.closest('.hrInvoiceRemoveLine');

            if (!removeBtn) {
                return;
            }

            var rows = body.querySelectorAll('.hr-invoice-line-row');

            if (rows.length <= 1) {
                alert('At least one invoice item row is required.');
                return;
            }

            removeBtn.closest('tr').remove();
            renumberRows();
            calculateTotals();
        });

        body.addEventListener('input', calculateTotals);
        body.addEventListener('change', calculateTotals);
    }

    document.querySelectorAll('.hr-invoice-calc-input').forEach(function (input) {
        input.addEventListener('input', calculateTotals);
        input.addEventListener('change', calculateTotals);
    });

    if (applyDiscount) {
        applyDiscount.addEventListener('change', updateDiscountVisibility);
    }

    if (discountMode) {
        discountMode.addEventListener('change', updateDiscountVisibility);
    }

    updateDiscountVisibility();
    renumberRows();
    calculateTotals();
});
